import sys, os, site
print("executable:", sys.executable)
print("version:", sys.version)
for p in sys.path:
    print("path:", p)
for mod in ["openpyxl", "pandas", "xlrd"]:
    try:
        __import__(mod)
        print(mod, "OK", getattr(sys.modules[mod], "__file__", ""))
    except Exception as e:
        print(mod, "MISSING", type(e).__name__)
print("cwd:", os.getcwd())
print("site dirs:", site.getsitepackages())

import os, subprocess, sys

# Check common python interpreters
candidates = [
    "/usr/bin/python3", "/usr/local/bin/python3", "/opt/homebrew/bin/python3",
    sys.executable,
]
seen = set()
for c in candidates:
    if not c or c in seen:
        continue
    seen.add(c)
    if os.path.exists(c):
        try:
            out = subprocess.run([c, "-c", "import openpyxl, sys; print(openpyxl.__version__); print(sys.executable)"],
                                 capture_output=True, text=True, timeout=30)
            print(c, "->", out.stdout.strip() or out.stderr.strip()[:200])
        except Exception as e:
            print(c, "ERR", e)

# Find openpyxl dirs under likely roots
roots = ["/usr/lib/python3", "/usr/local/lib", "/opt", "/mlx_devbox", "/home/tiger"]
found = []
for root in roots:
    if not os.path.isdir(root):
        continue
    for dirpath, dirnames, filenames in os.walk(root):
        # prune heavy dirs
        dirnames[:] = [d for d in dirnames if d not in ("node_modules", ".git", "__pycache__")]
        if "openpyxl" in dirnames or any(f.startswith("openpyxl") for f in filenames):
            found.append(dirpath)
            if len(found) > 20:
                break
    if len(found) > 20:
        break
print("openpyxl locations:", found[:20])

